.iWZnhl { position: absolute; left: 0px; top: 0px; transform: translate(429px, 29px); z-index: 1111; }
.jCsjPF { position: relative; display: block; box-shadow: rgba(20, 20, 20, 0.08) 0px 24px 48px 0px; line-height: 1.5; padding-inline: 16px; padding-block: 10px; text-decoration: none; overflow-wrap: break-word; font-size: 12px; border-radius: 4px; background-color: rgb(20, 20, 20); color: rgb(255, 255, 255); max-inline-size: 232px; }
.jCsjPF a, .jCsjPF button[data-button-use^="link"], .jCsjPF button[data-button-use="transparent"], .jCsjPF button[data-button-use="unstyled"] { color: rgb(255, 255, 255); text-decoration: underline; text-underline-offset: 24%; font-weight: 600; }
.jCsjPF a:hover, .jCsjPF button[data-button-use^="link"]:hover, .jCsjPF button[data-button-use="transparent"]:hover, .jCsjPF button[data-button-use="unstyled"]:hover { color: rgb(230, 230, 230); }
.jCsjPF a:active, .jCsjPF button[data-button-use^="link"]:active, .jCsjPF button[data-button-use="transparent"]:active, .jCsjPF button[data-button-use="unstyled"]:active { color: rgb(179, 179, 179); }
.jCsjPF svg[data-icon-name] { fill: rgb(255, 255, 255); }
.jCsjPF svg[data-icon-name="ExternalLink"] { fill: rgb(255, 255, 255) !important; }
